from pathlib import Path
import yaml,html,json,hashlib
p=Path('specs/041-popcorn-feedback-and-learning'); content=yaml.safe_load((p/'learning-content.yaml').read_text(encoding='utf-8-sig'))
for r in content['rows']:
 if r['id']=='recovery':
  r['lesson']='Missed the jump? Your steps and bridges are safe.'
content['recovery_saved_variant']='After committed saved recipe only: Missed the jump? Your skill and bridges are safe.'
(p/'learning-content.yaml').write_text(yaml.safe_dump(content,sort_keys=False,allow_unicode=True),encoding='utf-8')
d=yaml.safe_load((p/'map.yaml').read_text(encoding='utf-8')); next(x for x in d['devices'] if x['id']=='controller')['settings']['learning_content']=content
(p/'map.yaml').write_text(yaml.safe_dump(d,sort_keys=False,allow_unicode=True),encoding='utf-8')
plan=(p/'plan.md').read_text(encoding='utf-8-sig').replace('start its separate cosmetic halo and call target.accept(input_player,false) once to reuse hit_sound.','start its separate cosmetic halo and retain the existing single target.accept(input_player,false) call to reuse hit_sound; do not add a second accept call.').replace('Recovery selects honest copy only after actual teleport return status, preserving base lesson beneath temporary override.','Recovery selects honest copy only after actual teleport return status, preserving base lesson beneath temporary override. Before teaching POP commit say steps are safe; only after commit may the saved-skill variant say skill is safe.')
(p/'plan.md').write_text(plan,encoding='utf-8')
# Exact table and simple course review, not a native runtime screenshot.
rows=''.join('<tr><td>'+html.escape(r['id'])+'<small>'+html.escape(r['trigger'])+'</small></td><td>'+html.escape(r['lesson'])+'</td><td>'+html.escape(r['action'])+'</td></tr>' for r in content['rows'])
contract=next(x for x in d['devices'] if x['id']=='controller')['settings']['course_contract']
svg=['<svg viewBox="0 0 1020 360" xmlns="http://www.w3.org/2000/svg">']
# Crop preserved course frame for readable deck diagram.
def pt(v):return (60+v[0]*27,30+(v[1]-13)*26)
ns={n['id']:n for n in contract['nodes']}
for e in contract['jump_edges']:
 a,b=pt(ns[e['source']]['center']),pt(ns[e['destination']]['center']); svg.append(f'<path d="M{a[0]},{a[1]} L{b[0]},{b[1]}" stroke="#8192a6" stroke-width="3" stroke-dasharray="8 6"/>')
for n in contract['nodes']:
 x,y=pt(n['center']);w=n['size'][0]*27;h=n['size'][1]*26
 svg.append(f'<rect x="{x-w/2}" y="{y-h/2}" width="{w}" height="{h}" rx="12" fill="#fff3c9" stroke="#dcb354" stroke-width="2"/><text x="{x}" y="{y+4}" text-anchor="middle" font-size="17" fill="#354052">{n["id"]}</text>')
for r in contract['receivers']:
 x,y=pt(r['position']); svg.append(f'<circle cx="{x}" cy="{y}" r="17" fill="none" stroke="#61cdbb" stroke-width="4"/><text x="{x}" y="{y+5}" text-anchor="middle" font-size="13" fill="#263b38">{r["target_id"]}</text>')
svg.append('<text x="70" y="330" font-size="17" fill="#354052">Existing mirrored route: start at right → teach → five jumps → either branch → final skill shot</text></svg>')
svg=''.join(svg)
page='''<!doctype html><html><head><meta charset="utf-8"><title>041 learning and feedback review</title><style>body{margin:0;padding:28px 42px;background:#eef2f6;color:#263444;font:17px Arial}h1{font-size:30px;margin:0 0 9px}h2{font-size:22px;margin:18px 0 8px}.sub{color:#536276}.panel{background:white;border-radius:14px;padding:16px 22px;margin-top:15px} .scene{display:grid;grid-template-columns:2fr 1fr;gap:20px}.card{background:#172c42;color:white;border-left:5px solid #61cdbb;padding:16px;font-size:19px;line-height:1.45;border-radius:10px}.recipe{color:#f9d785}.action{font-weight:bold}table{width:100%;border-collapse:collapse;background:white;font-size:16px}td,th{padding:9px 12px;border-bottom:1px solid #dce3eb;text-align:left;vertical-align:top}th{background:#dce6ef}td:first-child{width:29%;font-weight:bold}td:nth-child(2){width:40%}small{display:block;color:#596779;font-size:13px;margin-top:4px;font-weight:normal}.pill{display:inline-block;padding:6px 10px;background:#ffe7b1;border-radius:8px}svg{width:100%}.note{font-size:15px;line-height:1.5}</style></head><body><h1>Popcorn Parkour: feedback + learning</h1><div class="sub">041 • planning preview • Producer → Planner • geometry preserved • conceptual HUD/effects, not a game screenshot</div><div class="scene panel"><div>'''+svg+'''</div><div><h2>Accepted shot</h2><p>One short pop + hollow glowing pulse.<br>Starts ≤0.15s; fades at 0.5s.<br>Machine disappears on existing timing.</p><h2>Actual outcome</h2><p>Existing flourish + “saved / bridge ready” only after commit.</p><span class="pill">Asset/HUD checks still open</span></div></div><div class="scene panel"><div><h2>Standing-view card: first reuse committed</h2><div class="card">One shot ran all three saved steps.<br><span class="recipe">PopBridge = LOAD &gt; HEAT &gt; POP.</span><br><span class="action">Jump onto the new popcorn.</span></div></div><div class="note"><h2>Readable while playing</h2>One card persists until the next meaningful action. Lower-left intent keeps aim clear; journal masks the card. Retry cues last 2s; new progress wins immediately. No quiz, pause or caption queue.</div></div><h2>Exact lesson and next-action copy</h2><div class="note">Each row also shows the stable recipe after commit, or draft recipe with accepted step count beforehand. Reuse beats stay 0.25s; lessons never depend on reading those fast beats.</div><table><tr><th>Real trigger</th><th>Lesson</th><th>Next action</th></tr>'''+rows+'''</table><div class="panel note">Recovery uses “steps” before recipe commit; after commit it may say “Your skill and bridges are safe.” Wrong-order NEXT follows the actual prefix. No accepted pop/halo on rejected, repeated, consumed, stale or foreign hits. Replay/Return/reset stop all effects and clear outdated lessons. Both branches and once-only reward stay unchanged.<br><strong>Readiness blocked:</strong> actual halo asset/lifecycle, pop audio bindings/settings and HUD/journal native placement remain unverified. Preview is an approval proposal, not implementation evidence.</div></body></html>'''
(p/'generated/learning-review.html').write_text(page,encoding='utf-8')
(p/'evidence/content-preview.json').write_text(json.dumps({'learning_content_sha256':hashlib.sha256((p/'learning-content.yaml').read_bytes()).hexdigest(),'visual':'generated/learning-review.html','note':'Exact copy embedded in map settings, therefore bound by generated review digest. Supplemental visual is not native game evidence.'},indent=2),encoding='utf-8')
